namespace Lokad.Onnx.Bench;

using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using Lokad.Onnx;

// Replay-backed voice-model benchmark cases (PLAN.md Milestone 5). Inputs
// load from the hash-pinned replay fixtures under
// models/voice-fixtures/replay (generated by the ignored
// .agent/voice-probe/gen_replay.py); a missing replay file fails the case
// loudly instead of substituting a different input. Named tensors match
// the graph contracts recorded in PLAN.md.
static class VoiceModelCases
{
    // Documented long-window gate: the 10-second segmentation operating
    // point amplifies cross-implementation rounding through high-gain
    // normalization channels and recurrence (see the Milestone 3
    // investigation in PLAN.md); every kernel in isolation matches ORT to
    // 4e-6 or better and ORT self-noise is 6.9e-05 on the same point.
    public const double SegLongTolerance = 2e-4;

    public static string ReplayDir(string root) =>
        Path.Combine(root, "models", "voice-fixtures", "replay");

    public static Dictionary<string, ITensor> EmbeddingInputs(string root)
    {
        return LoadNamed(root, new (string, string)[]
        {
            ("fbank_features", "embedding_fbank.npy"),
        });
    }

    public static Dictionary<string, ITensor> DecoderStep1Inputs(string root)
    {
        return LoadNamed(root, new (string, string)[]
        {
            ("encoder_outputs", "decoder_enc.npy"),
            ("targets", "decoder_tgt.npy"),
            ("target_length", "decoder_tlen.npy"),
            ("input_states_1", "decoder_s0_1.npy"),
            ("input_states_2", "decoder_s0_2.npy"),
        });
    }

    public static Dictionary<string, ITensor> DecoderChainedInputs(string root, float[] state1, float[] state2)
    {
        var feeds = LoadNamed(root, new (string, string)[]
        {
            ("encoder_outputs", "decoder_enc.npy"),
            ("targets", "decoder_tgt.npy"),
            ("target_length", "decoder_tlen.npy"),
        });
        feeds["input_states_1"] = Named("input_states_1", new DenseTensor<float>(state1, new[] { 2, 1, 640 }));
        feeds["input_states_2"] = Named("input_states_2", new DenseTensor<float>(state2, new[] { 2, 1, 640 }));
        return feeds;
    }

    public static Dictionary<string, ITensor> EncoderInputs(string root)
    {
        return LoadNamed(root, new (string, string)[]
        {
            ("audio_signal", "encoder_mel128.npy"),
            ("length", "encoder_len128.npy"),
        });
    }

    public static Dictionary<string, ITensor> SegmentationInputs(string root)
    {
        return LoadNamed(root, new (string, string)[]
        {
            ("waveform", "seg_real_10s.npy"),
        });
    }

    static Dictionary<string, ITensor> LoadNamed(string root, (string name, string file)[] entries)
    {
        var d = new Dictionary<string, ITensor>(StringComparer.Ordinal);
        foreach (var (name, file) in entries)
        {
            string path = Path.Combine(ReplayDir(root), file);
            if (!File.Exists(path))
                throw new InvalidOperationException("voice replay asset missing: " + path
                    + " (models/ is git-ignored; generate it with .agent/voice-probe/gen_replay.py).");
            d[name] = Named(name, ReadNpy(path));
        }
        return d;
    }

    static ITensor Named(string name, ITensor tensor)
    {
        tensor.Name = name;
        return tensor;
    }

    static ITensor ReadNpy(string path)
    {
        byte[] raw = File.ReadAllBytes(path);
        if (raw.Length < 10 || raw[0] != 0x93 || raw[1] != (byte)'N')
            throw new InvalidDataException("Bad NPY magic: " + path + ".");
        int headerOff = raw[6] == 1 ? 10 : 12;
        int headerLen = raw[6] == 1
            ? raw[8] | (raw[9] << 8)
            : raw[8] | (raw[9] << 8) | (raw[10] << 16) | (raw[11] << 24);
        string header = System.Text.Encoding.ASCII.GetString(raw, headerOff, headerLen);
        if (header.Contains("'fortran_order': True"))
            throw new InvalidDataException("Fortran-order NPY is not supported: " + path + ".");
        string descr = header.Contains("<f4") ? "<f4" : header.Contains("<i4") ? "<i4" : header.Contains("<i8") ? "<i8" : throw new InvalidDataException("Unsupported NPY dtype: " + path + ".");
        int s0 = header.IndexOf('(');
        int s1 = header.IndexOf(')');
        var parts = header.Substring(s0 + 1, s1 - s0 - 1).Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
        int[] shape = parts.Length == 0 ? Array.Empty<int>() : parts.Select(p => int.Parse(p)).ToArray();
        int n = 1;
        foreach (var d in shape) n *= d;
        int size = descr == "<i8" ? 8 : 4;
        byte[] payload = new byte[n * size];
        Array.Copy(raw, headerOff + headerLen, payload, 0, payload.Length);
        return descr switch
        {
            "<f4" => ToTensor<float>(payload, shape),
            "<i4" => ToTensor<int>(payload, shape),
            _ => ToTensor<long>(payload, shape),
        };
    }

    static DenseTensor<T> ToTensor<T>(byte[] payload, int[] shape) where T : unmanaged
    {
        var values = new T[payload.Length / System.Runtime.InteropServices.Marshal.SizeOf<T>()];
        Buffer.BlockCopy(payload, 0, values, 0, payload.Length);
        return new DenseTensor<T>(values, shape);
    }
}
